// Plan:
// 1. Parse the input JSON array of integers.
// 2. Iterate through the array, summing the integers.
// 3. Return the sum as a JSON value.

use serde_json::Value;

pub fn solve(input: Value) -> Value {
    // Ensure the input is an array
    let arr = input.as_array().expect("Input must be an array");

    // Initialize sum to zero
    let mut sum: i64 = 0;

    // Iterate through the array and sum the integers
    for item in arr {
        // Ensure each item is an integer
        let num = item.as_i64().expect("Array elements must be integers");
        sum += num;
    }

    // Return the sum as a JSON value
    Value::Number(serde_json::Number::from(sum))
}
